/**
 * @description Token cache for connection auth classes (IntegrationHub.IConnectionAuth). A token is kept in memory for
 * the current transaction or job and, when the org has Platform Cache with a default org partition, in Cache.Org so
 * later jobs reuse it. Without Platform Cache everything still works: the auth class just logs in once per job.
 * Keys come from the connection Id. Never store a token in a field.
 * @group Integration Hub
 */
public with sharing class IntegrationHubTokenCache {

    /** Platform Cache keeps a value at least this long (seconds); a shorter life is kept in memory only. */
    private static final Integer CACHE_MIN_SECONDS = 300;
    /** Platform Cache keeps a value at most this long (seconds). */
    private static final Integer CACHE_MAX_SECONDS = 172800;
    private static final String KEY_PREFIX = 'ihtoken';

    /** Tokens of this transaction or job by key: the token and when it expires (epoch milliseconds). */
    private static Map<String, Entry> memory = new Map<String, Entry>();

    /** False once Platform Cache failed in this transaction (no cache, no default partition): memory only. */
    @TestVisible
    private static Boolean usePlatformCache = true;

    private class Entry {
        private final String token;
        private final Long expiresAt;

        Entry(String value, Long expiresAtMillis) {
            token = value;
            expiresAt = expiresAtMillis;
        }
    }

    /**
     * @description The cached token of a connection, while it is still valid.
     * @param connectionId the connection
     * @return the token, or null when none is cached or it expired
     */
    public static String cachedToken(Id connectionId) {
        String key = keyOf(connectionId);
        if (key == null) {
            return null;
        }
        Entry hit = memory.get(key);
        if (hit != null && hit.expiresAt > System.currentTimeMillis()) {
            return hit.token;
        }
        memory.remove(key);
        return fromPlatformCache(key);
    }

    /**
     * @description Keeps a token for a number of seconds. Use a little less than the token's own life (for example
     * expires_in minus 60) so a token is never sent just as it expires.
     * @param connectionId the connection
     * @param token the token (blank removes it)
     * @param ttlSeconds how long to keep it, in seconds (blank or below 1: removed)
     */
    public static void putToken(Id connectionId, String token, Integer ttlSeconds) {
        String key = keyOf(connectionId);
        if (key == null) {
            return;
        }
        if (String.isBlank(token) || ttlSeconds == null || ttlSeconds < 1) {
            removeToken(connectionId);
            return;
        }
        memory.put(key, new Entry(token, System.currentTimeMillis() + ttlSeconds * 1000L));
        if (ttlSeconds >= CACHE_MIN_SECONDS) {
            toPlatformCache(key, token, Math.min(ttlSeconds, CACHE_MAX_SECONDS));
        }
    }

    /**
     * @description Forgets the token of a connection, for example after the system answered 401.
     * @param connectionId the connection
     */
    public static void removeToken(Id connectionId) {
        String key = keyOf(connectionId);
        if (key == null) {
            return;
        }
        memory.remove(key);
        removeFromPlatformCache(key);
    }

    /**
     * @description The cache key of a connection: letters and digits only, as Platform Cache requires.
     * @param connectionId the connection
     * @return the key, or null without a connection
     */
    @TestVisible
    private static String keyOf(Id connectionId) {
        return connectionId == null ? null : KEY_PREFIX + String.valueOf(connectionId);
    }

    /* No Platform Cache, no default partition, or the partition is full: memory only from now on. */
    private static void toPlatformCache(String key, String token, Integer ttlSeconds) {
        if (!usePlatformCache) {
            return;
        }
        try {
            Cache.Org.put(key, token, ttlSeconds);
        } catch (Exception e) {
            usePlatformCache = false;
        }
    }

    private static void removeFromPlatformCache(String key) {
        if (!usePlatformCache) {
            return;
        }
        try {
            Cache.Org.remove(key);
        } catch (Exception e) {
            usePlatformCache = false;
        }
    }

    private static String fromPlatformCache(String key) {
        if (!usePlatformCache) {
            return null;
        }
        try {
            Object value = Cache.Org.get(key);
            return value instanceof String ? (String) value : null;
        } catch (Exception e) {
            usePlatformCache = false;
            return null;
        }
    }
}
